    const pw = Object.assign({ cur: '', nw: '', cf: '' }, st.pw || {});
    const setPw = (k, v) => this.setState({ pw: Object.assign({}, pw, { [k]: v }) });
    const pwErr = !pw.cur ? 'Enter your current password' : passwordProblem(pw.nw, ME.email, ME.name) ? passwordProblem(pw.nw, ME.email, ME.name) : pw.nw !== pw.cf ? "The new passwords don't match" : pw.nw === pw.cur ? 'Choose a password you have not used here' : '';
    // two-step verification
