    if (setup) { try { const q = QRCode.create(setup.uri, { errorCorrectionLevel: 'M' }); qrN = q.modules.size; for (let y = 0; y < qrN; y++) for (let x = 0; x < qrN; x++) if (q.modules.get(y, x)) qr.push({ x, y }); } catch (e) {} }
    const tfaKey = setup ? setup.secret.match(/.{1,4}/g).join(' ') : '';
