    const ago = (t) => { const m = Math.round((Date.now() - new Date(t).getTime()) / 60000); return m < 5 ? 'active now' : m < 60 ? 'last active ' + m + ' minutes ago' : m < 1440 ? 'last active ' + Math.round(m / 60) + (Math.round(m / 60) === 1 ? ' hour ago' : ' hours ago') : 'last active ' + fmtD(new Date(t)); };
    const devs = (ME.sessions || []).map((x) => Object.assign({ id: x.id, current: x.current, d: (x.ip ? x.ip + ' · ' : '') + (x.current ? 'this device' : ago(x.lastSeen)) }, agentName(x.agent || '')));
