      saveName: async () => { if (!nameDraft.trim() || nameDraft.trim() === name) return; const r = await this.run('setName', { name: nameDraft.trim() }, 'Display name saved'); if (r) this.setState({ nameDraft: undefined }); },
      photo, hasPhoto: !!photo, noPhoto: !photo, photoLabel: photo ? 'Change your photo' : 'Add a photo',
      onPhoto: (ev) => { const fl = ev.target.files && ev.target.files[0]; if (fl) this.readImage(fl, 256, (u) => { if (u) setPhoto(u); else this.flash('That image could not be read'); }); },
      clearPhoto: () => setPhoto(''),
      email, emailPending: emailMode === 'pending', emailDraft: newEmail,
      emailSame: newEmail.trim().toLowerCase() === email.toLowerCase(), emailBtn: newEmail.trim().toLowerCase() === email.toLowerCase() ? 'opacity:.45;cursor:default' : '',
